<template>
  <div class="commerce-page admin-commerce"><header class="commerce-heading"><div><p class="eyebrow">QUALITY BEFORE VISIBILITY</p><h1>广告与商品审核</h1><p class="intro">核对每一份商品与广告，让校园里的推荐值得信任。</p></div><el-button size="large" :loading="loading" @click="load">刷新审核列表</el-button></header><CarouselManager /><div class="review-type-tabs"><button :class="{active:kind==='all'}" @click="switchKind('all')"><i class="ph ph-squares-four" /> 全部 <span>{{ Number(counts.products||0)+Number(counts.campaigns||0) }}</span></button><button :class="{active:kind==='products'}" @click="switchKind('products')"><i class="ph ph-package" /> 商品审核 <span>{{ counts.products||0 }}</span></button><button :class="{active:kind==='campaigns'}" @click="switchKind('campaigns')"><i class="ph ph-megaphone-simple" /> 广告审核 <span>{{ counts.campaigns||0 }}</span></button></div><section class="surface"><div class="toolbar"><div class="filter-pills"><button v-for="f in filters" :key="f.value" :class="{active:status===f.value}" @click="status=f.value;page=1;load()">{{ f.label }}</button></div><span class="review-tip">{{ kind==='all'?'统一查看商品与广告申请':kind==='products'?'通过后在师生周边商城上架':'通过后可在上方选择加入首页轮播' }}</span></div><el-table :data="rows" v-loading="loading" empty-text="当前没有需要查看的申请"><el-table-column :label="kind==='all'?'商品 / 广告信息':kind==='products'?'商品信息':'广告信息'" min-width="280"><template #default="{row}"><div class="review-product"><img :src="row.imageUrl" :alt="row.title" /><div><strong>{{ row.title }}</strong><el-tag v-if="kind==='all'" size="small" effect="plain" style="margin-left:8px">{{ row.itemType==='products'?'商品':'广告' }}</el-tag><small>{{ row.content }}</small><span v-if="(row.itemType||kind)==='products'">¥ {{ Number(row.price).toFixed(2) }}</span><span v-else>{{ row.targetType==='MERCHANT'?'关联商家主页':'关联商品 · '+row.productTitle }}</span></div></div></template></el-table-column><el-table-column label="合作商家" min-width="145"><template #default="{row}"><strong class="review-merchant">{{ row.merchantName }}</strong><p class="review-sub">{{ row.city || '合作商家' }}</p></template></el-table-column><el-table-column label="审核状态" width="155"><template #default="{row}"><CommerceStatus :status="row.reviewStatus" /></template></el-table-column><el-table-column label="提交时间" min-width="145"><template #default="{row}"><span class="review-sub">{{ String(row.createdAt||'').replace('T',' ').slice(0,16) }}</span></template></el-table-column><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button type="primary" :plain="row.reviewStatus!=='PENDING'" @click="open(row)">{{ row.reviewStatus==='PENDING'?'查看并审核':'查看详情' }} <i class="ph ph-arrow-up-right" /></el-button></template></el-table-column></el-table><el-pagination v-if="total>12" v-model:current-page="page" class="commerce-pager" :page-size="12" :total="total" layout="total, prev, pager, next" @current-change="load" /></section>
    <el-dialog v-model="visible" :title="current?.itemType==='products'?'商品审核详情':'广告审核详情'" width="780px" class="commerce-dialog admin-commerce-dialog" top="6vh" :close-on-click-modal="false"><template v-if="current"><div class="review-hero"><img :src="current.imageUrl" :alt="current.title" /><div><CommerceStatus :status="current.reviewStatus" /><h2 style="margin-top:12px">{{ current.title }}</h2><p>{{ current.merchantName }} · {{ current.itemType==='products'?current.city+'发货':current.targetType==='MERCHANT'?'关联商家主页':'关联商品：'+current.productTitle }}</p><strong v-if="current.targetType!=='MERCHANT'" class="preview-price">¥ {{ Number(current.price).toFixed(2) }}</strong></div></div><div class="review-content"><p class="review-description">{{ current.content }}</p><ContentBlocks v-if="current.itemType==='products'" :value="current.blocks||'[]'" /><img v-else class="campaign-art" :src="current.imageUrl" alt="广告主图" /></div><div v-if="current.reviewReason" class="old-reason">上次审核说明：{{ current.reviewReason }}</div><el-form v-if="['PENDING','APPROVED'].includes(current.reviewStatus)" label-position="top"><el-form-item :label="current.reviewStatus==='APPROVED'?'下架原因（必填）':'审核说明（驳回时必填）'"><el-input v-model="reason" type="textarea" :rows="3" maxlength="500" show-word-limit placeholder="请写下具体原因，帮助商家完善内容" /></el-form-item></el-form></template><template #footer><div class="dialog-footer"><span>审核针对当前版本，内容修改后需重新审核。</span><div><el-button :disabled="saving" @click="visible=false">关闭</el-button><el-button v-if="current?.reviewStatus==='PENDING'||current?.reviewStatus==='APPROVED'" type="danger" plain :loading="saving" @click="decide('REJECTED')">{{ current.reviewStatus==='APPROVED'?'下架内容':'驳回申请' }}</el-button><el-button v-if="current?.reviewStatus==='PENDING'" type="primary" :loading="saving" @click="decide('APPROVED')">审核通过</el-button></div></div></template></el-dialog>
  </div>
</template>
<script setup>
import { ref,onMounted } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { reviewCounts,reviewList,reviewItem } from '@/api/merchant'
import CommerceStatus from '@/components/CommerceStatus.vue'
import ContentBlocks from '@/components/ContentBlocks.vue'
import CarouselManager from '@/components/CarouselManager.vue'
const kind=ref('all'),status=ref(''),rows=ref([]),total=ref(0),counts=ref({}),page=ref(1),loading=ref(false),visible=ref(false),current=ref(null),reason=ref(''),saving=ref(false)
const filters=[{value:'',label:'全部记录'},{value:'PENDING',label:'等待审核'},{value:'APPROVED',label:'已通过'},{value:'REJECTED',label:'已驳回 / 已下架'}]
let version=0
async function load(){const stamp=++version;loading.value=true;try{const [list,count]=await Promise.all([reviewList(kind.value,{page:page.value,size:12,status:status.value}),reviewCounts()]);if(stamp!==version)return;rows.value=list.data.list;total.value=list.data.total;counts.value=count.data;if(!rows.value.length&&page.value>1){page.value--;await load()}}catch{}finally{if(stamp===version)loading.value=false}}
function switchKind(value){kind.value=value;page.value=1;load()}
function open(row){current.value={...row,itemType:row.itemType||kind.value};reason.value='';visible.value=true}
async function decide(decision){if(saving.value)return;if(decision==='REJECTED'&&!reason.value.trim()){ElMessage.warning('请填写具体的驳回或下架原因');return}if(decision==='APPROVED'){const ok=await ElMessageBox.confirm(current.value.itemType==='products'?'通过后商品将对师生开放浏览和下单。':'通过后可在“选择商家广告”中将其加入首页轮播。','确认审核通过',{confirmButtonText:'确认通过',cancelButtonText:'再核对一下'}).then(()=>true).catch(()=>false);if(!ok)return}saving.value=true;try{await reviewItem(current.value.itemType,current.value.id,{decision,reason:reason.value,revision:current.value.revision});ElMessage.success(decision==='APPROVED'?'审核已通过':'处理结果已反馈给商家');visible.value=false;await load();window.dispatchEvent(new Event('commerce-review-changed'))}catch{}finally{saving.value=false}}
onMounted(load)
</script>
<style scoped>
.review-type-tabs{display:flex;flex-wrap:wrap;gap:15px;margin-bottom:24px}.review-type-tabs button{display:flex;align-items:center;gap:10px;border:1px solid #d9d8e5;background:#f7f7fb;color:#7d7c96;border-radius:12px;padding:15px 24px;font-size:14px;cursor:pointer}.review-type-tabs button>i{font-size:21px}.review-type-tabs button>span{font-size:11px;border-radius:6px;padding:3px 7px;background:#e0dfed;color:#6c6a97}.review-type-tabs button.active{background:#353451;color:#e4e3f8;border-color:#353451}.review-type-tabs button.active>span{background:#504e70;color:#c8c6f3}.review-tip{font-size:11px;color:#9493ab}.review-product{display:flex;align-items:center;gap:15px}.review-product>img{width:76px;height:70px;object-fit:cover;border-radius:10px;background:#e7e6f1;flex-shrink:0}.review-product strong{font-size:13px}.review-product small{display:-webkit-box;-webkit-line-clamp:1;-webkit-box-orient:vertical;overflow:hidden;color:#9291aa;font-size:11px;margin:6px 0;line-height:1.7}.review-product>div>span{color:#5d5a9b;font-size:11px}.review-merchant{font-size:12px;font-weight:500}.review-sub{font-size:11px;color:#8b8aa5;margin:5px 0}.review-description{font-size:13px;line-height:1.9;white-space:pre-wrap;color:#6f6d90}.old-reason{background:#edecfc;padding:12px 16px;border-radius:10px;color:#6561aa;font-size:12px;line-height:1.8;margin-bottom:20px}.campaign-art{width:100%;object-fit:contain;max-height:320px;border-radius:10px}
</style>
